written = []
for p in PREDS:
    assert set(p.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, p["case_id"]
    assert 0.0 <= p["confidence"] <= 1.0
    assert set(p["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    path = os.path.join(OUT, p["case_id"] + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(p, f, ensure_ascii=False, indent=1)
        f.write("\n")
    sz = os.path.getsize(path)
    with open(path, encoding="utf-8") as f:
        back = json.load(f)
    assert back["case_id"] == p["case_id"] and back["trigger"] == p["trigger"]
    written.append((p["case_id"], path, sz))

cm = sum(1 for p in PREDS if p["trigger"]["changed_main"])
ru = sum(1 for p in PREDS if p["trigger"]["reserve_used"])
di = sum(1 for p in PREDS if p["trigger"]["disputed"])
print("total", len(PREDS), "written", len(written))
print("trigger counts changed_main/reserve_used/disputed:", cm, ru, di)
for cid, path, sz in written:
    print(cid, sz, path)
